def validate_scope(tenant_id, allowed_case_ids, case_id, write, can_write):
    if type(tenant_id) is not str or type(case_id) is not str:
        raise TypeError('id_not_string')
    if type(allowed_case_ids) is not list or any(type(item) is not str for item in allowed_case_ids):
        raise TypeError('allowlist_invalid')
    if type(write) is not bool or type(can_write) is not bool:
        raise TypeError('flag_not_bool')
    if not tenant_id.strip() or not case_id.strip() or any(not item.strip() for item in allowed_case_ids):
        raise ValueError('blank_id')
    if len(set(allowed_case_ids)) != len(allowed_case_ids):
        raise ValueError('duplicate_case')
    if case_id not in allowed_case_ids:
        raise PermissionError('case_forbidden')
    if write and not can_write:
        raise PermissionError('write_forbidden')
