from datetime import datetime, timezone

def validate_retention(observed_at, expires_at, now, max_days=90):
    if any(type(value) is not str for value in (observed_at, expires_at, now)):
        raise TypeError('timestamp_not_string')
    if type(max_days) is not int:
        raise TypeError('max_days_not_int')
    if max_days <= 0:
        raise ValueError('max_days_invalid')
    def parse(value):
        try:
            parsed = datetime.strptime(value, '%Y-%m-%dT%H:%M:%SZ').replace(tzinfo=timezone.utc)
        except ValueError as error:
            raise ValueError('timestamp_invalid') from error
        if parsed.strftime('%Y-%m-%dT%H:%M:%SZ') != value:
            raise ValueError('timestamp_not_canonical')
        return parsed
    observed, expires, current = map(parse, (observed_at, expires_at, now))
    if observed > current:
        raise ValueError('source_in_future')
    lifetime = int((expires - observed).total_seconds())
    if lifetime <= 0 or lifetime > max_days * 86400:
        raise ValueError('retention_invalid')
    return lifetime

import re

def select_evidence(evidence):
    if type(evidence) is not list:
        raise TypeError('evidence_not_list')
    projected = {}
    for item in evidence:
        if type(item) is not dict:
            raise TypeError('evidence_item_not_dict')
        if set(item) != {'kind', 'ref', 'digest', 'body'}:
            raise ValueError('evidence_shape_invalid')
        if any(type(item[key]) is not str for key in item):
            raise TypeError('evidence_value_not_string')
        kind = item['kind']
        if kind not in {'document', 'sql'} or kind in projected:
            raise ValueError('evidence_kind_invalid')
        if not item['ref'].strip() or re.fullmatch(r'[0-9a-f]{64}', item['digest']) is None:
            raise ValueError('evidence_identity_invalid')
        projected[kind] = {'kind': kind, 'ref': item['ref'], 'digest': item['digest']}
    if set(projected) != {'document', 'sql'}:
        raise ValueError('evidence_incomplete')
    return [projected['document'], projected['sql']]

