import hashlib
import json

def memory_digest(memory):
    if type(memory) is not dict:
        raise TypeError('memory_not_dict')
    def validate(value):
        if value is None or type(value) in (bool, int, str):
            return
        if type(value) is list:
            for item in value:
                validate(item)
            return
        if type(value) is dict:
            if any(type(key) is not str for key in value):
                raise TypeError('key_not_string')
            for item in value.values():
                validate(item)
            return
        raise TypeError('value_not_json_contract')
    validate(memory)
    encoded = json.dumps(memory, sort_keys=True, separators=(',', ':'), ensure_ascii=False).encode('utf-8')
    return hashlib.sha256(encoded).hexdigest()

