import re

def write_decision(current_digest, current_revision, incoming_digest, expected_revision):
    if current_digest is not None and type(current_digest) is not str:
        raise TypeError('current_digest_invalid')
    if type(incoming_digest) is not str:
        raise TypeError('incoming_digest_invalid')
    if type(current_revision) is not int or type(expected_revision) is not int:
        raise TypeError('revision_not_int')
    if current_revision < 0 or expected_revision < 0:
        raise ValueError('revision_negative')
    digest_pattern = r'[0-9a-f]{64}'
    if re.fullmatch(digest_pattern, incoming_digest) is None:
        raise ValueError('incoming_digest_invalid')
    if current_digest is not None and re.fullmatch(digest_pattern, current_digest) is None:
        raise ValueError('current_digest_invalid')
    if current_digest is None:
        if current_revision != 0:
            raise ValueError('missing_record_has_revision')
        if expected_revision != 0:
            raise RuntimeError('revision_conflict')
        return {'action': 'create', 'revision': 1}
    if current_revision == 0:
        raise ValueError('existing_record_without_revision')
    if incoming_digest == current_digest:
        return {'action': 'replay', 'revision': current_revision}
    if expected_revision != current_revision:
        raise RuntimeError('revision_conflict')
    return {'action': 'update', 'revision': current_revision + 1}

