def approval_transition(before, after):
    if type(before) is not str or type(after) is not str:
        raise TypeError('status_not_string')
    statuses = {'draft', 'awaiting_approval', 'approved', 'rejected'}
    if before not in statuses or after not in statuses:
        raise ValueError('status_transition_invalid')
    if before == after:
        return False
    allowed = {
        ('draft', 'awaiting_approval'),
        ('awaiting_approval', 'approved'),
        ('awaiting_approval', 'rejected'),
    }
    if (before, after) not in allowed:
        raise ValueError('status_transition_invalid')
    return True

from copy import deepcopy

def apply_status_update(record, new_status, expected_revision):
    if type(record) is not dict:
        raise TypeError('record_not_dict')
    if set(record) != {'case_id','facts','status','revision'}:
        raise ValueError('record_shape_invalid')
    if type(record['case_id']) is not str or type(record['status']) is not str or type(new_status) is not str:
        raise TypeError('record_string_invalid')
    if not record['case_id'].strip():
        raise ValueError('case_id_blank')
    if type(record['facts']) is not dict:
        raise TypeError('facts_not_dict')
    if type(record['revision']) is not int or type(expected_revision) is not int:
        raise TypeError('revision_not_int')
    if record['revision'] <= 0:
        raise ValueError('revision_invalid')
    if expected_revision != record['revision']:
        raise RuntimeError('revision_conflict')
    statuses = {'draft','awaiting_approval','approved','rejected'}
    allowed = {('draft','awaiting_approval'),('awaiting_approval','approved'),('awaiting_approval','rejected')}
    if record['status'] not in statuses or new_status not in statuses or (record['status'], new_status) not in allowed:
        raise ValueError('status_transition_invalid')
    result = deepcopy(record)
    result['status'] = new_status
    result['revision'] += 1
    return result

