import re

def rank_episodes(question, episodes):
    if type(question) is not str or type(episodes) is not list:
        raise TypeError('ranking_input_invalid')
    if not question.strip():
        raise ValueError('question_blank')
    seen_ids, seen_sequences, ranked = set(), set(), []
    query_tokens = set(re.findall(r'[a-z0-9]+', question.lower()))
    for episode in episodes:
        if type(episode) is not dict:
            raise TypeError('episode_not_dict')
        if set(episode) != {'id','sequence','text'}:
            raise ValueError('episode_shape_invalid')
        if type(episode['id']) is not str or type(episode['text']) is not str or type(episode['sequence']) is not int:
            raise TypeError('episode_field_invalid')
        if not episode['id'].strip() or not episode['text'].strip() or episode['sequence'] <= 0:
            raise ValueError('episode_value_invalid')
        if episode['id'] in seen_ids or episode['sequence'] in seen_sequences:
            raise ValueError('episode_duplicate')
        seen_ids.add(episode['id']); seen_sequences.add(episode['sequence'])
        overlap = len(query_tokens & set(re.findall(r'[a-z0-9]+', episode['text'].lower())))
        if overlap:
            ranked.append((-overlap, -episode['sequence'], episode['id']))
    ranked.sort()
    return [episode_id for _, _, episode_id in ranked]

