def pack_context(prefix, episodes, max_characters):
    if type(prefix) is not str or type(episodes) is not list:
        raise TypeError('context_input_invalid')
    if type(max_characters) is not int:
        raise TypeError('max_characters_not_int')
    if not prefix.strip() or max_characters <= 0 or max_characters < len(prefix):
        raise ValueError('context_budget_invalid')
    if any(type(item) is not str for item in episodes):
        raise TypeError('episode_not_string')
    if any(not item.strip() or '\n' in item or '\r' in item for item in episodes):
        raise ValueError('episode_invalid')
    if len(set(episodes)) != len(episodes):
        raise ValueError('episode_duplicate')
    result = prefix
    for episode in episodes:
        line = '\n- ' + episode
        if len(result) + len(line) > max_characters:
            break
        result += line
    return result

