def recall_record(records, tenant_id, case_id, now):
    if type(records) is not list or type(tenant_id) is not str or type(case_id) is not str or type(now) is not str:
        raise TypeError('recall_input_invalid')
    if not tenant_id.strip() or not case_id.strip():
        raise ValueError('scope_blank')
    def parse(value):
        try:
            parsed = datetime.strptime(value, '%Y-%m-%dT%H:%M:%SZ').replace(tzinfo=timezone.utc)
        except (TypeError, ValueError) as error:
            raise ValueError('timestamp_invalid') from error
        if parsed.strftime('%Y-%m-%dT%H:%M:%SZ') != value:
            raise ValueError('timestamp_invalid')
        return parsed
    current = parse(now)
    matches = []
    for record in records:
        if type(record) is not dict:
            raise TypeError('record_not_dict')
        if set(record) != {'tenant_id','case_id','expires_at','summary'}:
            raise ValueError('record_shape_invalid')
        if any(type(value) is not str for value in record.values()):
            raise TypeError('record_value_not_string')
        if not record['tenant_id'].strip() or not record['case_id'].strip() or not record['summary'].strip():
            raise ValueError('record_value_blank')
        parse(record['expires_at'])
        if record['tenant_id'] == tenant_id and record['case_id'] == case_id:
            matches.append(record)
    if not matches:
        raise LookupError('memory_not_found')
    if len(matches) != 1:
        raise ValueError('duplicate_memory')
    if parse(matches[0]['expires_at']) <= current:
        raise LookupError('memory_expired')
    return deepcopy(matches[0])

