def merge_episodes(existing, incoming, expected_next, max_events, max_bytes):
    if type(existing) is not list or type(incoming) is not list:
        raise TypeError('episodes_not_list')
    if any(type(value) is not int for value in (expected_next, max_events, max_bytes)):
        raise TypeError('limit_not_int')
    if expected_next <= 0 or max_events <= 0 or max_bytes <= 0:
        raise ValueError('limit_invalid')
    combined = existing + incoming
    for episode in combined:
        if type(episode) is not dict:
            raise TypeError('episode_not_dict')
        if set(episode) != {'sequence','text'}:
            raise ValueError('episode_shape_invalid')
        if type(episode['sequence']) is not int or type(episode['text']) is not str:
            raise TypeError('episode_field_invalid')
        if episode['sequence'] <= 0 or not episode['text'].strip():
            raise ValueError('episode_value_invalid')
    if expected_next != len(existing) + 1:
        raise RuntimeError('revision_conflict')
    if incoming and incoming[0]['sequence'] != expected_next:
        raise RuntimeError('revision_conflict')
    if [item['sequence'] for item in combined] != list(range(1, len(combined) + 1)):
        raise ValueError('episode_sequence_invalid')
    if len(combined) > max_events:
        raise OverflowError('event_limit_exceeded')
    if sum(len(item['text'].encode('utf-8')) for item in combined) > max_bytes:
        raise OverflowError('byte_limit_exceeded')
    return deepcopy(combined)

