def audit_memory_lifecycle(events):
    if type(events) is not list:
        raise TypeError('events_not_list')
    if not events:
        raise ValueError('events_empty')
    actions = {'create','replay','status','forget'}
    for event in events:
        if type(event) is not dict:
            raise TypeError('event_not_dict')
        if set(event) != {'sequence','action','revision'}:
            raise ValueError('event_shape_invalid')
        if type(event['sequence']) is not int or type(event['revision']) is not int or type(event['action']) is not str:
            raise TypeError('event_field_invalid')
        if event['sequence'] <= 0 or event['revision'] <= 0 or event['action'] not in actions:
            raise ValueError('event_value_invalid')
    if [event['sequence'] for event in events] != list(range(1, len(events) + 1)):
        raise ValueError('event_sequence_invalid')
    if events[0]['action'] != 'create' or events[0]['revision'] != 1:
        raise ValueError('lifecycle_must_create')
    revision = 1; forgotten = False
    for index, event in enumerate(events[1:], start=1):
        action = event['action']
        if action == 'create':
            raise ValueError('duplicate_create')
        if action == 'status':
            revision += 1
        if event['revision'] != revision:
            raise ValueError('event_revision_invalid')
        if action == 'forget':
            if forgotten or index != len(events) - 1:
                raise ValueError('forget_not_terminal')
            forgotten = True
    return {'revision': revision, 'forgotten': forgotten, 'events': len(events)}
